// api.ts
import axios, { AxiosRequestConfig } from 'axios';
interface AxiosResponse<T = any> {
  data: T;
  status: number;
  statusText: string;
  headers: any;
  config: AxiosRequestConfig;
  request?: any;
}
const BASE_URL = process.env.REACT_APP_API_URL;
const callApi = axios.create({
  baseURL: BASE_URL,
  timeout: 10000,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Request Interceptor
callApi.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token'); // หรือจาก secure storage
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);


// ✅ Response Interceptor: จัดการ Error
callApi.interceptors.response.use(
  (response) => response,
  async (error) => {
    console.log('Axios Error:', error);

    // ถ้าไม่มี response -> network error
    if (!error.response) {
      alert('Network error หรือ CORS ปัญหา');

    // ✅ ถ้า 401 และยังไม่เคย retry -> ลอง refresh token
    // if (error.response.status === 401 && !originalRequest._retry) {
    //   originalRequest._retry = true;

      try {
        const refreshToken = localStorage.getItem('refreshToken');
        if (!refreshToken) {
          throw new Error('No refresh token');
        }

        // เรียก API refresh token
        const res = await axios.post(`${process.env.REACT_APP_API_URL}/auth/refresh`, {
          refreshToken,
        });

        const newAccessToken = res.data.accessToken;
        localStorage.setItem('accessToken', newAccessToken);

        // แนบ token ใหม่แล้ว retry request เดิม
        // originalRequest.headers.Authorization = `Bearer ${newAccessToken}`;
        // return callApi(originalRequest);
      } catch (refreshError) {
        console.error('Refresh token failed:', refreshError);
        localStorage.clear();
        window.location.replace('/login');
      }
    }

    // ✅ ถ้าเป็น 403 หรือ refresh token ใช้ไม่ได้
    if (error.response.status === 403) {
      localStorage.clear();
      window.location.replace('/login');
    }

    return Promise.reject(error);
  }
);


export default callApi;
